action.command:
echo "=== tiles.localhost (tilejson) ==="; curl -sk --resolve tiles.localhost:443:127.0.0.1 https://tiles.localhost/styles/light.json -o /dev/null -w "HTTP %{http_code}
"; curl -sk --resolve tiles.localhost:443:127.0.0.1 "https://tiles.localhost/data/germany.json" -o /dev/null -w "tilejson: HTTP %{http_code}
"
echo "=== files.localhost WebDAV (unauth -> forward_auth) ==="; curl -sk --resolve files.localhost:443:127.0.0.1 https://files.localhost/ -o /dev/null -w "unauth: HTTP %{http_code}
"
TOKEN=$(curl -sk --resolve api.localhost:443:127.0.0.1 -X POST https://api.localhost/api/v1/auth/login/ -H "Content-Type: application/json" -d '{"username":"admin","password":"Admin!LocalDev123"}' | tr -d '
' | sed 's/.*"access":"\([^"]*\)".*/\1/')
echo "=== files.localhost WebDAV PROPFIND (auth) ==="; curl -sk --resolve files.localhost:443:127.0.0.1 -X PROPFIND -H "Authorization: Bearer $TOKEN" https://files.localhost/ -o /tmp/webdav.xml -w "auth PROPFIND: HTTP %{http_code}
"; head -c 300 /tmp/webdav.xml
